// The content model for Things I've Built.
//
// Three layers with different owners:
//   Registry     content/things/*.md, content/topics.yaml   editorial, written by Jamie or an agent
//                content/artifacts/<thing id>/*             files from the projects, each listed by its thing
//   Ledger       content/history/<year>.yaml                editorial, often proposed by the collector
//   Observations data/observations/**/*.json                generated by `npm run collect`, never hand-edited
//
// Observations never change editorial fields. Status is a decision; activity is evidence.

type DatePrecision = string; // YYYY, YYYY-MM, or YYYY-MM-DD, exactly as the source states it.

export type Status = 'active' | 'dormant' | 'retired' | 'abandoned' | 'archived';
export const statuses: Status[] = ['active', 'dormant', 'retired', 'abandoned', 'archived'];

type GitHubSource = {
  kind: 'github';
  repository: string; // owner/name
  role: string; // implementation, theme, historical, ...
  path?: string; // directory scope inside the repository
};
type WebsiteSource = {
  kind: 'website';
  url: string;
  role: string; // website, reference, ...
  sitemap?: string;
  feed?: string; // RSS, Atom, or JSON Feed
};
export type ThingSource = GitHubSource | WebsiteSource;

export type Connection = {
  to: string;
  label: string;
  detail: string;
  source: string;
  kind?: 'lineage';
};

export type Story = {
  color: string;
  introduction: string;
  engineering: string[];
  stack: string[];
  source?: string;
  sourceLabel?: string;
  related: string[];
  questions: string[];
  started?: string; // display text, for example "Published since 2017"
};

// A file the project itself made or used, kept in content/artifacts/<thing id>/ and published beside the
// thing's page at /things/<thing id>/artifacts/<file>. Any kind of file: an image is shown, anything else is
// offered as a download, with an image of it when a browser cannot show it. What the project left behind,
// chosen by hand; never something regenerated.
export type Artifact = {
  file: string; // its name in the thing's artifact folder
  title: string;
  caption?: string;
  date?: DatePrecision; // when the file was made, as far as it is known
  source?: string; // a public page that shows or describes it
  preview?: string; // an image in the same folder that shows a file a browser cannot
};
// What the loader read from each artifact file, keyed `<thing id>/<file>`: measured, never written by hand.
export type ArtifactFile = { bytes: number; width?: number; height?: number };

export type Thing = {
  id: string; // from the file name
  title: string;
  summary: string;
  collection: string;
  status: Status;
  url: string | null;
  started?: DatePrecision;
  ended?: DatePrecision;
  topics: string[];
  sources: ThingSource[];
  connections: Connection[];
  story?: Story;
  artifacts?: Artifact[];
  body: string; // Markdown. The project's story, if any.
};

export type Topic = { id: string; title: string; description: string };

export type EventKind = 'launch' | 'milestone' | 'retirement' | 'archive' | 'development';
export const eventKinds: EventKind[] = ['launch', 'milestone', 'retirement', 'archive', 'development'];
export type HistoryEvent = {
  id: string;
  date: DatePrecision;
  kind: EventKind;
  title: string;
  summary: string;
  source: string;
  things: string[];
};

export type Registry = {
  things: Thing[];
  topics: Topic[];
  history: HistoryEvent[];
  artifactFiles?: Map<string, ArtifactFile>; // set by loadRegistry
};

// Observations. Each one names when it was observed and what it is evidence of.
export type MonthCount = { month: string; count: number };
export type CommitActivity = {
  path: string | null;
  branch: string;
  since: string;
  until: string;
  count: number;
  complete: boolean; // false when a page limit made the count a lower bound
  months: MonthCount[];
  latestCommit: { date: string; url: string } | null;
};
export type GitHubObservation = {
  kind: 'github';
  repository: string;
  url: string;
  observedAt: string;
  repositoryCreatedAt: string; // repository creation, not project launch
  archived: boolean;
  description: string;
  stars: number; // lifetime totals with no dates: reach, not activity
  forks: number;
  languages: { name: string; bytes: number }[];
  release: { name: string; date: string; url: string } | null;
  activity: CommitActivity[];
};
export type SitemapObservation = {
  url: string;
  pages: number;
  newestModified: string | null; // modification evidence, not a launch date
  months: MonthCount[]; // lastmod counts for the last 12 months
  complete: boolean;
};
export type FeedObservation = {
  url: string;
  title: string | null;
  items: number; // items present in the feed document
  newestPublished: string | null;
  months: MonthCount[]; // published counts for the last 12 months, within the feed's window
};
export type WebObservation = {
  kind: 'web';
  url: string;
  observedAt: string;
  sitemap: SitemapObservation | null;
  feed: FeedObservation | null;
};
export type TinylyticsObservation = {
  kind: 'tinylytics';
  url: string; // the site root, matched to website sources with the same root
  observedAt: string;
  since: string;
  until: string;
  hits: number; // human page views in the window; reach, not activity
  months: MonthCount[];
};
export type WaybackObservation = {
  kind: 'wayback';
  url: string; // the captured URL, unwrapped from a Wayback link
  observedAt: string;
  firstCapture: string | null; // existence evidence, not a launch date
  latestCapture: string | null; // may be someone else's page after a domain lapsed
  years: { year: string; days: number }[]; // days with a 200 capture
};
// A capture of a website's front page, stored as a JPEG beside its observation. What the site looked
// like on that day: evidence of the thing, never a statement about it.
export type ScreenshotObservation = {
  kind: 'screenshot';
  url: string; // the site root that was captured
  observedAt: string; // when it was captured
  image: string; // the JPEG's file name, beside this observation
  sha256: string;
  width: number;
  height: number;
};
// Every commit on a public repository's default branch, read from a commits-only clone. Git is already an
// append-only log, so each run re-reads the whole history and the observation changes only when a commit
// lands. Commits by bots (dependabot, the collector itself) are left out: they are upkeep, not work.
export type CommitAuthor = 'me' | 'agent' | 'others';
export type Agent = 'claude' | 'codex';
export type CommitEntry = {
  sha: string; // the first twelve hex digits
  date: string; // committer date: when it landed on the branch
  subject: string; // the first line; a merge commit's pull request title
  by: CommitAuthor;
  agents?: Agent[]; // the agents a commit names, by author or co-author trailer; absent when it names none
  pr?: number;
  paths?: string[]; // the registry's directory scopes this commit touched, for repositories that have them
};
export type CommitLogObservation = {
  kind: 'commits';
  repository: string;
  url: string;
  observedAt: string;
  branch: string;
  commits: CommitEntry[]; // newest first
  tags: { name: string; date: string }[]; // newest first
};
// Every item a thing's own feed has carried. A feed holds only its newest items, so the collector keeps each
// one it has seen: the log only grows, and an item that ages out of the feed stays.
export type Publication = {
  url: string | null;
  id?: string; // the item's guid or id, when it has no link
  title: string | null;
  excerpt?: string; // the opening words, for an item with no title (Micro.blog posts)
  date: string;
};
export type PublicationsObservation = {
  kind: 'publications';
  url: string; // the website source, keyed like its web observation
  feed: string;
  observedAt: string;
  items: Publication[]; // newest first
};
export type Observation =
  | GitHubObservation
  | WebObservation
  | TinylyticsObservation
  | WaybackObservation
  | ScreenshotObservation
  | CommitLogObservation
  | PublicationsObservation;

// Stable file names for observations, derived from the source identity so shared sources are stored once.
const slug = (value: string) =>
  value
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
export const githubKey = (repository: string) => slug(repository.split('/')[1]);
export const websiteKey = (url: string) => slug(url);
